"use strict";
// A stripe painter in the shape of small CommonJS packages that wrap
// buf.fill: each function hands its own untyped parameters on, so the kind
// of the value, of the offsets and of the encoding is known only when the
// call runs. Every function checks that fill answers its receiver.
function paint() {
  return Buffer.alloc(6, 0x2e);
}
function fill1(v) {
  var b = paint();
  return b.fill(v) === b ? b : "NOT THE RECEIVER";
}
function fill2(v, a) {
  var b = paint();
  return b.fill(v, a) === b ? b : "NOT THE RECEIVER";
}
function fill3(v, a, c) {
  var b = paint();
  return b.fill(v, a, c) === b ? b : "NOT THE RECEIVER";
}
function fill4(v, a, c, e) {
  var b = paint();
  return b.fill(v, a, c, e) === b ? b : "NOT THE RECEIVER";
}
function fillLiteral(a) {
  return paint().fill("ab", a);
}
function fillNumber(a, c) {
  return paint().fill(1, a, c);
}
function fillPassed(b, v, a, c, e) {
  return b.fill(v, a, c, e);
}
var fills = [
  ["undefined", undefined],
  ["0", 0],
  ["7", 7],
  ["257", 257],
  ["-1", -1],
  ["1.9", 1.9],
  ["NaN", NaN],
  ["'a'", "a"],
  ["'ab'", "ab"],
  ["''", ""],
  ["'6162'", "6162"],
  ["'é'", "é"],
  ["true", true],
  ["null", null],
  ["buffer", Buffer.from("xy")],
  ["u8", new Uint8Array([1, 2])],
  ["u16", new Uint16Array([258, 772])],
  ["emptyBuffer", Buffer.alloc(0)],
  ["emptyU8", new Uint8Array(0)],
  ["{}", {}],
  ["[5]", [5]],
  [
    "valueOf",
    {
      valueOf: function () {
        return 66;
      },
    },
  ],
  ["symbol", Symbol("s")],
  ["bigint", BigInt(3)],
];
var encodings = [
  ["undefined", undefined],
  ["utf8", "utf8"],
  ["hex", "hex"],
  ["base64", "base64"],
  ["UTF-8", "UTF-8"],
  ["nope", "nope"],
  ["''", ""],
  ["5", 5],
  ["null", null],
];
var seconds = [
  ["undefined", undefined],
  ["0", 0],
  ["2", 2],
  ["6", 6],
  ["7", 7],
  ["-1", -1],
  ["1.5", 1.5],
  ["NaN", NaN],
  ["'hex'", "hex"],
  ["'nope'", "nope"],
  ["''", ""],
  ["null", null],
  ["'2'", "2"],
  ["true", true],
];
var ranges = [
  ["1,4", 1, 4],
  ["4,1", 4, 1],
  ["0,7", 0, 7],
  ["0,'utf8'", 0, "utf8"],
  ["0,'nope'", 0, "nope"],
  ["undefined,3", undefined, 3],
  ["1,undefined", 1, undefined],
  ["1,null", 1, null],
  ["'1',3", "1", 3],
  ["2,2", 2, 2],
  ["1,2.5", 1, 2.5],
];
function show(thunk) {
  try {
    var v = thunk();
    return typeof v === "string" ? v : v.toString("hex");
  } catch (e) {
    return e.name + (e.code ? " " + e.code : "") + ": " + String(e.message).split("\n")[0];
  }
}
exports.report = function () {
  var lines = [];
  fills.forEach(function (fill) {
    lines.push(
      "fill1 v=" +
        fill[0] +
        " -> " +
        show(function () {
          return fill1(fill[1]);
        }),
    );
    seconds.forEach(function (second) {
      lines.push(
        "fill2 v=" +
          fill[0] +
          " a=" +
          second[0] +
          " -> " +
          show(function () {
            return fill2(fill[1], second[1]);
          }),
      );
    });
    ranges.forEach(function (range) {
      lines.push(
        "fill3 v=" +
          fill[0] +
          " " +
          range[0] +
          " -> " +
          show(function () {
            return fill3(fill[1], range[1], range[2]);
          }),
      );
    });
    encodings.forEach(function (encoding) {
      lines.push(
        "fill4 v=" +
          fill[0] +
          " 1,4 enc=" +
          encoding[0] +
          " -> " +
          show(function () {
            return fill4(fill[1], 1, 4, encoding[1]);
          }) +
          " | " +
          show(function () {
            return fillPassed(paint(), fill[1], 1, 4, encoding[1]);
          }),
      );
    });
  });
  seconds.forEach(function (second) {
    lines.push(
      "fillLiteral a=" +
        second[0] +
        " -> " +
        show(function () {
          return fillLiteral(second[1]);
        }),
    );
  });
  ranges.forEach(function (range) {
    lines.push(
      "fillNumber " +
        range[0] +
        " -> " +
        show(function () {
          return fillNumber(range[1], range[2]);
        }),
    );
  });
  return lines;
};
